GatewayClient.send_with_retry

def send_with_retry(self, document, attempts=3):
    for attempt in range(attempts):
        response = self.post(document)
        if response.ok:
            return response
        time.sleep(2 ** attempt)
    raise GatewayUnavailable(document.number)
